if(rows.length<100){console.error('那读数逐字只有 '+rows.length+' 行、 100 次**要** 100 **行**、 按 C-105 报缺');process.exit(1);}if(fails.length){console.error('那零启动失败**没过**（ 失败的有 '+fails.length+' 次、 第一**行** = '+JSON.stringify(fails[0].slice(0,iV+1))+'）');process.exit(1);}if(uniq.size<pids.length){console.error('那 pid **不**都**不**一样（ 唯一的有 '+uniq.size+' 个、 **它****证明**那**不是**那 **100** **次**重启**）');process.exit(1);}console.log('RESTART_100_OK takenAt='+takenAt+' n='+rows.length+' failed=0 unique_pids='+uniq.size);
